srcDoc.css:
body {
  margin: 0;
  background: #eef1f5;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 18px;
}

.print-button {
  display: block;
  margin: 0 auto 14px;
  width: 220px;
  height: 42px;
  border: 0;
  border-radius: 7px;
  background: #101828;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.invoice {
  width: 210mm;
  min-height: 297mm;
  margin: 0 auto;
  background: white;
  padding: 16mm;
  box-sizing: border-box;
  box-shadow: 0 18px 50px rgba(15, 23, 42, 0.16);
}

.top-line {
  height: 7px;
  margin: -16mm -16mm 14mm;
  background: linear-gradient(90deg, #101828, #2563eb, #0f766e);
}

.header {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid #d0d5dd;
  padding-bottom: 16px;
}

.brand {
  display: flex;
  gap: 14px;
}

.logo {
  width: 90px;
  max-height: 70px;
  object-fit: contain;
}

.company-name {
  font-size: 24px;
  font-weight: 900;
}

.meta {
  margin-top: 7px;
  color: #667085;
  font-size: 12px;
  line-height: 1.45;
}

.title {
  text-align: right;
  min-width: 250px;
}

.badge {
  display: inline-block;
  padding: 6px 10px;
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

.title h1 {
  margin: 10px 0 5px;
  font-size: 32px;
}

.doc-no {
  font-size: 17px;
  font-weight: 900;
}

.info-grid,
.party-grid,
.bottom-grid {
  display: grid;
  gap: 12px;
  margin-top: 16px;
}

.info-grid {
  grid-template-columns: repeat(4, 1fr);
}

.party-grid {
  grid-template-columns: 1fr 1fr;
}

.bottom-grid {
  grid-template-columns: 1fr 320px;
  align-items: start;
}

.box {
  border: 1px solid #d0d5dd;
  padding: 10px;
}

.label {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 800;
  margin-bottom: 5px;
}

.value {
  font-size: 13px;
  font-weight: 800;
}

table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 16px;
}

th {
  background: #101828;
  color: white;
  text-align: left;
  padding: 9px 8px;
  font-size: 11px;
}

td {
  padding: 8px;
  border-bottom: 1px solid #eaecf0;
  font-size: 12px;
  vertical-align: top;
}

.right {
  text-align: right;
  white-space: nowrap;
}

.product-code {
  font-weight: 900;
}

.product-name {
  color: #667085;
  font-size: 11px;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid #d0d5dd;
  font-size: 13px;
}

.summary-row.total {
  background: #101828;
  color: white;
  font-size: 16px;
  font-weight: 900;
}

.fiscal {
  font-size: 10px;
  color: #475467;
  word-break: break-all;
  line-height: 1.5;
}

.fiscal-qr-box {
  margin-top: 10px;
  display: inline-block;
  text-align: center;
  border: 1px solid #d0d5dd;
  padding: 8px;
}

.qr {
  width: 72px;
  height: 72px;
  image-rendering: pixelated;
}

.fiscal-qr-box div,
.barcode-box div {
  margin-top: 4px;
  color: #667085;
  font-size: 9px;
  font-weight: 700;
}

.barcode-footer {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 18px;
}

.barcode-box {
  border: 1px solid #d0d5dd;
  padding: 8px;
  text-align: center;
  min-height: 78px;
  box-sizing: border-box;
}

.barcode-box svg {
  width: 100%;
  max-height: 62px;
}

.footer {
  margin-top: 22px;
  padding-top: 10px;
  border-top: 1px solid #d0d5dd;
  text-align: center;
  color: #667085;
  font-size: 10px;
}

.empty {
  background: white;
  padding: 28px;
  text-align: center;
  color: #667085;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  .print-button {
    display: none;
  }
  .invoice {
    width: 210mm;
    min-height: 297mm;
    margin: 0;
    padding: 14mm;
    box-shadow: none;
  }
  .top-line {
    margin: -14mm -14mm 14mm;
  }
  .qr {
    width: 20mm;
    height: 20mm;
  }
  .barcode-footer {
    gap: 4mm;
    margin-top: 8mm;
  }
  .barcode-box {
    min-height: 24mm;
    padding: 2mm;
  }
}

