import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
import QRCode from "https://esm.sh/qrcode@1.5.3";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function pick(obj, keys, fallback = "") {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) return obj[key];
  }
  return fallback;
}

function money(value) {
  return Number(value || 0).toFixed(2);
}

function qty(value) {
  return Number(value || 0).toFixed(3);
}

function val(value) {
  return String(value ?? "");
}

function date(value) {
  if (!value) return "";
  return new Date(value).toLocaleDateString("en-GB");
}

function title(header) {
  return pick(header, ["documentType", "Document Type"]) === "CREDIT_NOTE"
    ? "CREDIT NOTE"
    : "SALES INVOICE";
}

function safeBarcode(value) {
  return String(value || "").replace(/[^A-Za-z0-9\-]/g, "").slice(0, 60);
}

function fiscalPayload(header) {
  const fiscalUrl = pick(header, ["fiscalVerificationUrl", "Fiscal Verification Url", "fiscal_qr_url"], "");
  if (fiscalUrl) return fiscalUrl;

  return [
    "FISCAL",
    `TYPE=${pick(header, ["documentType", "Document Type"], "SALES_INVOICE")}`,
    `NO=${pick(header, ["fiscalNumber", "Fiscal Number", "documentNumber", "Document Number"], "")}`,
    `DATE=${pick(header, ["documentDate", "Document Date"], "")}`,
    `TOTAL=${pick(header, ["totalAmount", "Total", "total_amount"], "")}`,
    `CURRENCY=${pick(header, ["currencyCode", "Currency"], "EUR")}`,
    `ZKI=${pick(header, ["zki", "ZKI"], "")}`,
    `JIR=${pick(header, ["jir", "JIR"], "")}`
  ].join("|");
}

function invoiceBarcodeValue(header) {
  return safeBarcode(
    pick(header, ["documentNumber", "Document Number", "fiscalNumber", "Fiscal Number", "documentId"], "")
  );
}

function returnBarcodeValue(header) {
  return safeBarcode(
    `RET-${pick(header, ["documentId", "Document ID"], "")}-${pick(header, ["documentNumber", "Document Number"], "")}`
  );
}

function App() {
  const model = appsmith.model || {};
  const h = model.header || {};
  const items = model.items || [];
  const taxes = model.taxes || [];

  const documentNumber = pick(h, ["documentNumber", "Document Number"], "");
  const fiscalNumber = pick(h, ["fiscalNumber", "Fiscal Number"], "");
  const documentId = pick(h, ["documentId", "Document ID"], "");

  const subtotalAmount = pick(h, ["subtotalAmount", "Subtotal", "subtotal_amount"], 0);
  const discountAmount = pick(h, ["discountAmount", "Discount", "discount_amount"], 0);
  const taxAmount = pick(h, ["taxAmount", "Tax", "tax_amount"], 0);
  const totalAmount = pick(h, ["totalAmount", "Total", "total_amount"], 0);
  const paidAmount = pick(h, ["paidAmount", "Paid", "paid_amount"], totalAmount);
  const currencyCode = pick(h, ["currencyCode", "Currency", "currency_code"], "EUR");

  const [fiscalQr, setFiscalQr] = React.useState("");
  const invoiceBarcodeRef = React.useRef(null);
  const returnBarcodeRef = React.useRef(null);

  const key = `${documentId}-${documentNumber}-${fiscalNumber}-${pick(h, ["jir", "JIR"], "")}`;

  React.useEffect(() => {
    async function buildFiscalQr() {
      if (!documentNumber) return;

      setFiscalQr(await QRCode.toDataURL(fiscalPayload(h), {
        margin: 1,
        width: 150,
        errorCorrectionLevel: "M"
      }));
    }

    buildFiscalQr();
  }, [key]);

  React.useEffect(() => {
    if (!documentNumber) return;

    if (invoiceBarcodeRef.current) {
      JsBarcode(invoiceBarcodeRef.current, invoiceBarcodeValue(h), {
        format: "CODE128",
        displayValue: true,
        fontSize: 12,
        height: 52,
        margin: 0
      });
    }

    if (returnBarcodeRef.current) {
      JsBarcode(returnBarcodeRef.current, returnBarcodeValue(h), {
        format: "CODE128",
        displayValue: true,
        fontSize: 12,
        height: 52,
        margin: 0
      });
    }
  }, [key]);

  if (!documentNumber) {
    return <div className="empty">No invoice data available.</div>;
  }

  return (
    <div className="page">
      <button className="print-button" onClick={() => window.print()}>Print / Ispis</button>

      <div className="invoice">
        <div className="top-line" />

        <div className="header">
          <div className="brand">
            {pick(h, ["companyLogoPath", "company_logo_path"], "") && (
              <img className="logo" src={pick(h, ["companyLogoPath", "company_logo_path"], "")} />
            )}
            <div>
              <div className="company-name">{pick(h, ["companyName", "Company"], "")}</div>
              <div className="meta">
                <div>{[pick(h, ["companyAddress"], ""), pick(h, ["companyPostalCode"], ""), pick(h, ["companyCity"], "")].filter(Boolean).join(", ")}</div>
                <div>Tax No: {pick(h, ["companyTaxNumber"], "-")}</div>
                <div>{[pick(h, ["companyEmail"], ""), pick(h, ["companyPhone"], "")].filter(Boolean).join(" | ")}</div>
              </div>
            </div>
          </div>

          <div className="title">
            <div className="badge">{title(h)}</div>
            <h1>{title(h)}</h1>
            <div className="doc-no">{fiscalNumber || documentNumber}</div>
            <div className="meta">Internal No: {documentNumber}</div>
          </div>
        </div>

        <div className="info-grid">
          <div className="box"><span className="label">Date</span><span className="value">{date(pick(h, ["documentDate", "Document Date"], ""))}</span></div>
          <div className="box"><span className="label">Issue Time</span><span className="value">{val(pick(h, ["issueTime", "Issue Time"], ""))}</span></div>
          <div className="box"><span className="label">Payment</span><span className="value">{val(pick(h, ["paymentMethod", "Payment Method"], ""))}</span></div>
          <div className="box"><span className="label">Currency</span><span className="value">{val(currencyCode)}</span></div>
        </div>

        <div className="party-grid">
          <div className="box">
            <span className="label">Customer</span>
            <div className="value">{pick(h, ["partnerName", "Customer", "partnerLegalName"], "-")}</div>
            <div className="meta">{pick(h, ["partnerCode", "Customer Code"], "")}</div>
            <div className="meta">{pick(h, ["partnerTaxNumber"], "") ? "Tax No: " + pick(h, ["partnerTaxNumber"], "") : ""}</div>
            <div className="meta">{[pick(h, ["partnerAddress"], ""), pick(h, ["partnerPostalCode"], ""), pick(h, ["partnerCity"], "")].filter(Boolean).join(", ")}</div>
          </div>

          <div className="box">
            <span className="label">Document Info</span>
            <div className="value">{pick(h, ["warehouseCode"], "")} {pick(h, ["warehouseName", "Warehouse"], "")}</div>
            <div className="meta">Created by: {pick(h, ["createdBy", "Created By"], "-")}</div>
            <div className="meta">Status: {pick(h, ["status", "Status"], "-")}</div>
            <div className="meta">Posting: {pick(h, ["postingStatus", "Posting Status"], "-")}</div>
          </div>
        </div>

        <table>
          <thead>
            <tr>
              <th>#</th>
              <th>Product / Service</th>
              <th>Description</th>
              <th className="right">Qty</th>
              <th>Unit</th>
              <th className="right">Price</th>
              <th className="right">Discount</th>
              <th className="right">Tax</th>
              <th className="right">Total</th>
            </tr>
          </thead>
          <tbody>
            {items.map((row, index) => (
              <tr key={index}>
                <td>{pick(row, ["lineNo", "Line No"], index + 1)}</td>
                <td>
                  <div className="product-code">{pick(row, ["productCode", "Product Code"], "")}</div>
                  <div className="product-name">{pick(row, ["productName", "Product Name"], "")}</div>
                </td>
                <td>{pick(row, ["description", "Description"], "")}</td>
                <td className="right">{qty(pick(row, ["quantity", "Quantity"], 0))}</td>
                <td>{pick(row, ["unitName", "unitCode", "Unit"], "")}</td>
                <td className="right">{money(pick(row, ["unitPrice", "Unit Price"], 0))}</td>
                <td className="right">{money(pick(row, ["discountAmount", "Discount"], 0))}</td>
                <td className="right">{money(pick(row, ["taxAmount", "Tax"], 0))}</td>
                <td className="right">{money(pick(row, ["lineTotal", "Total"], 0))}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="bottom-grid">
          <div>
            <div className="box fiscal">
              <div><b>ZKI:</b> {pick(h, ["zki", "ZKI"], "-")}</div>
              <div><b>JIR:</b> {pick(h, ["jir", "JIR"], "-")}</div>
              <div><b>Fiscal status:</b> {pick(h, ["fiscalStatus", "Fiscal Status"], "-")}</div>
              {pick(h, ["note", "Note"], "") && <div><b>Note:</b> {pick(h, ["note", "Note"], "")}</div>}

              <div className="fiscal-qr-box">
                {fiscalQr && <img className="qr" src={fiscalQr} />}
                <div>Fiscal verification</div>
              </div>
            </div>
          </div>

          <div className="box" style={{ padding: 0 }}>
            <div className="summary-row"><span>Subtotal</span><b>{money(subtotalAmount)} {currencyCode}</b></div>
            <div className="summary-row"><span>Discount</span><b>{money(discountAmount)} {currencyCode}</b></div>
            <div className="summary-row"><span>Tax</span><b>{money(taxAmount)} {currencyCode}</b></div>
            <div className="summary-row total"><span>Total</span><b>{money(totalAmount)} {currencyCode}</b></div>
            <div className="summary-row"><span>Paid</span><b>{money(paidAmount)} {currencyCode}</b></div>
          </div>
        </div>

        {taxes.length > 0 && (
          <table>
            <thead>
              <tr>
                <th>Tax Rate</th>
                <th className="right">Taxable</th>
                <th className="right">Tax</th>
                <th className="right">Total</th>
              </tr>
            </thead>
            <tbody>
              {taxes.map((tax, index) => (
                <tr key={index}>
                  <td>{money(pick(tax, ["taxRate", "Tax Rate"], 0))}%</td>
                  <td className="right">{money(pick(tax, ["taxableAmount", "Taxable"], 0))}</td>
                  <td className="right">{money(pick(tax, ["taxAmount", "Tax"], 0))}</td>
                  <td className="right">{money(pick(tax, ["totalAmount", "Total"], 0))}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        <div className="barcode-footer">
          <div className="barcode-box">
            <svg ref={invoiceBarcodeRef}></svg>
            <div>Invoice lookup</div>
          </div>

          <div className="barcode-box">
            <svg ref={returnBarcodeRef}></svg>
            <div>Return / complaint lookup</div>
          </div>
        </div>

        <div className="footer">This document was generated by Axon ERP.</div>
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
